-- 0072 AP Subject A development/management/strategy exam-style bank (A-47..A-68)

-- Validated AP Subject A four-choice questions.

-- Replaces generic/open-ended seed question_no=1 for targeted concepts.

PRAGMA foreign_keys = ON;



INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'요구사항 변경이 자주 발생하고 짧은 주기로 가치를 제공해야 하는 프로젝트에 일반적으로 더 적합한 접근은?','要件変更が頻繁で，短い周期で価値を提供する必要があるプロジェクトに，一般により適するアプローチはどれか。','["アジャイル開発","ウォータフォール開発だけ","ビッグバン移行だけ","ベンチマーク"]','["アジャイル開発","ウォータフォール開発だけ","ビッグバン移行だけ","ベンチマーク"]',0,'Agile','アジャイル開発','짧은 반복과 피드백을 통해 변화에 대응하기 쉽다.','短い反復とフィードバックによって変化へ対応しやすい。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-47' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'애자일 개발에 대한 설명으로 가장 적절한 것은?','アジャイル開発の説明として最も適切なものはどれか。','["短い反復で動作する成果物を継続的に改善する","文書を一切作成しない","要件変更を禁止する","全工程を必ず一度だけ実施する"]','["短い反復で動作する成果物を継続的に改善する","文書を一切作成しない","要件変更を禁止する","全工程を必ず一度だけ実施する"]',0,'짧은 반복으로 동작하는 결과물을 지속 개선','短い反復で動作する成果物を継続的に改善する','애자일은 문서 부재가 아니라 반복적 가치 전달과 피드백을 중시한다.','アジャイルは文書不要を意味せず，反復的な価値提供とフィードバックを重視する。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-47' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'계약상 요구사항이 매우 안정적이고 단계별 승인 산출물이 엄격히 요구되는 프로젝트에서 상대적으로 적용하기 쉬운 방식은?','契約上の要件が安定し，各工程の承認成果物が厳格に求められるプロジェクトで，相対的に適用しやすい方式はどれか。','["ウォータフォール","スクラムだけ","カンバンだけ","A/Bテスト"]','["ウォータフォール","スクラムだけ","カンバンだけ","A/Bテスト"]',0,'Waterfall','ウォータフォール','공정을 순차적으로 관리하고 단계별 산출물을 명확히 하는 특성과 잘 맞는다.','工程を順次管理し，各工程の成果物を明確にする特性と合いやすい。',2,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-47' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'다음 중 비기능 요구사항에 해당하는 것은?','次のうち，非機能要件に該当するものはどれか。','["利用者が注文を登録できる","95%の要求を2秒以内に応答する","管理者が商品を削除できる","利用者が履歴を検索できる"]','["利用者が注文を登録できる","95%の要求を2秒以内に応答する","管理者が商品を削除できる","利用者が履歴を検索できる"]',1,'95% 요청을 2초 이내 응답','95%の要求を2秒以内に応答する','성능 기준은 시스템이 얼마나 잘 동작해야 하는지를 나타내는 비기능 요구다.','性能基準は，システムがどの程度よく動作すべきかを示す非機能要件である。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-48' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'요구사항 문장으로 가장 적절한 것은?','要件の記述として最も適切なものはどれか。','["画面は速く表示する","使いやすくする","通常時の応答時間を95パーセンタイルで2秒以下とする","できるだけ安全にする"]','["画面は速く表示する","使いやすくする","通常時の応答時間を95パーセンタイルで2秒以下とする","できるだけ安全にする"]',2,'측정 가능한 응답시간 기준','通常時の応答時間を95パーセンタイルで2秒以下とする','검증 가능한 수치와 조건이 있는 요구사항이 모호성이 적다.','検証可能な数値と条件を含む要件は曖昧さが少ない。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-48' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'요구사항 정의에서 acceptance 기준을 명확히 하는 주된 목적은?','要件定義で受入れ基準を明確にする主な目的はどれか。','["完成判定を客観的に行えるようにする","開発者だけが仕様を変更できるようにする","テストを不要にする","全ての変更を禁止する"]','["完成判定を客観的に行えるようにする","開発者だけが仕様を変更できるようにする","テストを不要にする","全ての変更を禁止する"]',0,'완료 판정을 객관화','完成判定を客観的に行えるようにする','수용 기준은 요구가 충족되었는지 검증할 기준이 된다.','受入れ基準は，要件が満たされたかを検証する判断基準となる。',2,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-48' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'시간 순서에 따른 객체 간 메시지 교환을 표현하는 UML 다이어그램은?','時間順にオブジェクト間のメッセージ交換を表すUML図はどれか。','["クラス図","シーケンス図","ユースケース図","状態遷移図"]','["クラス図","シーケンス図","ユースケース図","状態遷移図"]',1,'Sequence diagram','シーケンス図','시퀀스 다이어그램은 객체 간 메시지 흐름을 시간축으로 표현한다.','シーケンス図はオブジェクト間のメッセージの流れを時間軸で表す。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-49' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'시스템의 정적 클래스 구조와 클래스 간 관계를 표현하는 UML 다이어그램은?','システムの静的なクラス構造とクラス間の関係を表すUML図はどれか。','["クラス図","アクティビティ図","シーケンス図","ユースケース図"]','["クラス図","アクティビティ図","シーケンス図","ユースケース図"]',0,'Class diagram','クラス図','클래스 다이어그램은 클래스, 속성, 연산, 관계의 정적 구조를 나타낸다.','クラス図はクラス，属性，操作，関係などの静的構造を表す。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-49' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'사용자 역할과 시스템이 제공하는 기능의 관계를 나타내는 데 가장 적절한 UML 다이어그램은?','利用者の役割とシステムが提供する機能の関係を表すのに最も適するUML図はどれか。','["ユースケース図","配置図","クラス図","タイミング図"]','["ユースケース図","配置図","クラス図","タイミング図"]',0,'Use Case diagram','ユースケース図','유스케이스 다이어그램은 액터와 시스템 기능의 관계를 표현한다.','ユースケース図はアクターとシステム機能との関係を表す。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-49' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'두 모듈 사이의 API 연동이 올바른지 확인하는 테스트 단계는?','二つのモジュール間のAPI連携が正しいかを確認するテスト段階はどれか。','["単体テスト","結合テスト","システムテスト","受入れテスト"]','["単体テスト","結合テスト","システムテスト","受入れテスト"]',1,'통합 테스트','結合テスト','인터페이스와 모듈 간 연동 검증은 결합 테스트의 핵심이다.','インタフェースやモジュール間連携の検証は結合テストの中心である。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-50' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'사용자 업무 요구를 만족하는지 최종 확인하는 테스트로 가장 적절한 것은?','利用者の業務要件を満たすかを最終確認するテストとして最も適切なものはどれか。','["受入れテスト","単体テスト","静的解析だけ","コードレビューだけ"]','["受入れテスト","単体テスト","静的解析だけ","コードレビューだけ"]',0,'인수 테스트','受入れテスト','인수 테스트는 사용자 관점에서 시스템이 수용 가능한지 확인한다.','受入れテストは利用者の観点でシステムを受け入れられるか確認する。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-50' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'개별 함수의 경계값과 반환값을 독립적으로 검증하는 데 가장 가까운 테스트 단계는?','個々の関数の境界値や戻り値を独立して検証するのに最も近いテスト段階はどれか。','["単体テスト","結合テスト","システムテスト","運用テスト"]','["単体テスト","結合テスト","システムテスト","運用テスト"]',0,'단위 테스트','単体テスト','작은 프로그램 단위의 내부 기능을 검증하는 것은 단위 테스트에 해당한다.','小さなプログラム単位の機能を検証するのは単体テストである。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-50' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'입력 가능한 나이가 18~65세일 때 경계값 분석의 대표 테스트 데이터 조합은?','入力可能な年齢が18～65歳のとき，境界値分析の代表的なテストデータの組合せはどれか。','["17,18,19,64,65,66","20,30,40,50","18,30,65だけ","0,100だけ"]','["17,18,19,64,65,66","20,30,40,50","18,30,65だけ","0,100だけ"]',0,'17,18,19,64,65,66','17,18,19,64,65,66','경계 직전·경계·경계 직후 값을 확인하는 것이 대표적이다.','境界の直前・境界値・直後の値を確認するのが代表的である。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-51' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'동등분할의 목적은?','同値分割の目的はどれか。','["同じ性質をもつ入力領域ごとに代表値を選ぶ","全入力値を必ず試す","境界値だけを試す","内部コードの全分岐を網羅する"]','["同じ性質をもつ入力領域ごとに代表値を選ぶ","全入力値を必ず試す","境界値だけを試す","内部コードの全分岐を網羅する"]',0,'같은 특성의 입력 영역별 대표값 선택','同じ性質をもつ入力領域ごとに代表値を選ぶ','동일하게 처리될 것으로 기대되는 입력 집합을 클래스별로 나눈다.','同じように処理されると期待できる入力集合をクラスに分ける。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-51' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'1~100만 유효한 입력에서 동등분할 관점의 대표값 선택으로 가장 적절한 것은?','1～100だけが有効な入力で，同値分割の観点から代表値を選ぶ組合せとして最も適切なものはどれか。','["50,0,101","1,2,3","99,100だけ","全ての整数"]','["50,0,101","1,2,3","99,100だけ","全ての整数"]',0,'50,0,101','50,0,101','유효 클래스 1개와 하한 미만·상한 초과의 무효 클래스를 대표하도록 고른다.','有効クラスと，下限未満・上限超過の無効クラスを代表する値を選ぶ。',2,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-51' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'소스코드 버전, 변경 이력, 베이스라인을 식별·통제하는 활동은?','ソースコードの版，変更履歴，ベースラインを識別・統制する活動はどれか。','["構成管理","負荷テスト","容量計画","名前解決"]','["構成管理","負荷テスト","容量計画","名前解決"]',0,'형상관리','構成管理','형상관리는 구성항목과 버전·변경을 식별하고 통제한다.','構成管理は構成品目と版・変更を識別し，統制する。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-52' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'리뷰의 주된 목적은?','レビューの主な目的はどれか。','["成果物の欠陥を早期に発見する","バックアップ容量を増やす","IPアドレスを割り当てる","暗号鍵を配布する"]','["成果物の欠陥を早期に発見する","バックアップ容量を増やす","IPアドレスを割り当てる","暗号鍵を配布する"]',0,'산출물 결함의 조기 발견','成果物の欠陥を早期に発見する','요구서·설계서·코드 등을 검토해 후공정 전에 문제를 찾는 것이 핵심이다.','要件書・設計書・コードなどを確認し，後工程へ進む前に欠陥を見つける。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-52' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'정식 릴리스 기준으로 승인된 구성항목 집합을 의미하는 것은?','正式なリリース基準として承認された構成品目の集合を表す用語はどれか。','["ベースライン","インシデント","スプリント","ワークアラウンド"]','["ベースライン","インシデント","スプリント","ワークアラウンド"]',0,'baseline','ベースライン','베이스라인은 승인된 기준 상태로 이후 변경은 통제 절차를 거친다.','ベースラインは承認された基準状態であり，以後の変更は統制手続を経る。',2,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-52' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'PERT에서 프로젝트 전체 기간을 결정하는 경로는?','PERTでプロジェクト全体の期間を決定する経路はどれか。','["クリティカルパス","最短経路","作業数が最少の経路","費用が最小の経路"]','["クリティカルパス","最短経路","作業数が最少の経路","費用が最小の経路"]',0,'critical path','クリティカルパス','여유시간이 0인 최장 소요 경로가 전체 완료시점을 좌우한다.','余裕時間が0の最長所要時間経路が全体の完了時点を左右する。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-53' AND t.type_no=1;

