SELECT NULL,t.id,1,'어떤 작업의 earliest start가 5일, latest start가 8일이면 slack은?','ある作業の最早開始時刻が5日，最遅開始時刻が8日のとき，余裕時間は何日か。','["0","3","5","13"]','["0","3","5","13"]',1,'3일','3日','slack=latest-earliest=8-5=3이다.','余裕時間=最遅開始-最早開始=8-5=3日である。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-53' AND t.type_no=2;

