SELECT NULL,t.id,1,'critical path상의 작업이 2일 지연되고 다른 여유가 없을 때 일반적으로 발생하는 것은?','クリティカルパス上の作業が2日遅延し，他に余裕がない場合，一般にどうなるか。','["プロジェクト完了も2日遅れる","影響はない","必ず2日早まる","コストだけ変わる"]','["プロジェクト完了も2日遅れる","影響はない","必ず2日早まる","コストだけ変わる"]',0,'프로젝트 완료도 2일 지연','プロジェクト完了も2日遅れる','critical path에는 여유가 없으므로 해당 지연이 전체 기간에 직접 반영된다.','クリティカルパスには余裕がないため，その遅延が全体期間へ直接反映される。',2,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-53' AND t.type_no=3;

