SELECT NULL,t.id,1,'EVM에서 EV=90, AC=110일 때 비용차이 CV는?','EVMでEV=90，AC=110のとき，コスト差異CVは幾つか。','["-20","20","0","200"]','["-20","20","0","200"]',0,'-20','-20','CV=EV-AC=90-110=-20이므로 비용 측면에서 불리하다.','CV=EV-AC=90-110=-20であり，コスト面で不利である。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-54' AND t.type_no=2;

