SELECT NULL,t.id,1,'EV=90, AC=100일 때 CPI는?','EV=90，AC=100のとき，CPIは幾つか。','["0.9","1.0","1.1","10"]','["0.9","1.0","1.1","10"]',0,'0.9','0.9','CPI=EV/AC=90/100=0.9다.','CPI=EV/AC=90/100=0.9である。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-55' AND t.type_no=1;

