SELECT NULL,t.id,1,'SPI가 0.8이라는 의미로 가장 적절한 것은?','SPIが0.8であることの意味として最も適切なものはどれか。','["計画より進捗が遅れている","計画より進捗が進んでいる","コストが必ず20%超過した","品質が20%低下した"]','["計画より進捗が遅れている","計画より進捗が進んでいる","コストが必ず20%超過した","品質が20%低下した"]',0,'계획보다 진척이 느림','計画より進捗が遅れている','SPI=EV/PV이고 1보다 작으면 계획 대비 실적 진척이 낮다.','SPI=EV/PVであり，1未満なら計画に対して進捗が遅れている。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-55' AND t.type_no=2;

