SELECT NULL,t.id,1,'위험의 발생 원인을 제거하여 해당 위험이 더 이상 발생하지 않게 하는 대응은?','リスクの発生原因を除去し，そのリスクが発生しないようにする対応はどれか。','["回避","軽減","転嫁","受容"]','["回避","軽減","転嫁","受容"]',0,'회피','回避','위험 자체를 없애는 방향은 회피다.','リスク自体をなくす方向の対応が回避である。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-56' AND t.type_no=1;

