SELECT NULL,t.id,1,'SLA 지표로 가장 적절한 것은?','SLAの指標として最も適切なものはどれか。','["月間可用性99.95%以上","システムはできるだけ速くする","担当者は努力する","障害は起こさない"]','["月間可用性99.95%以上","システムはできるだけ速くする","担当者は努力する","障害は起こさない"]',0,'측정 가능한 가용성 목표','月間可用性99.95%以上','SLA는 측정·검증 가능한 서비스 수준으로 표현하는 것이 적절하다.','SLAは測定・検証可能なサービス水準として定義するのが適切である。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-57' AND t.type_no=3;

