SELECT NULL,t.id,1,'반복 장애의 근본원인을 분석하고 재발방지책을 찾는 활동은?','繰り返し発生する障害の根本原因を分析し，再発防止策を検討する活動はどれか。','["問題管理","インシデント管理だけ","可用性計算","DNS管理"]','["問題管理","インシデント管理だけ","可用性計算","DNS管理"]',0,'Problem management','問題管理','problem 관리는 근본원인과 재발 방지에 초점을 둔다.','問題管理は根本原因の分析と再発防止に焦点を当てる。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-58' AND t.type_no=2;

