SELECT NULL,t.id,1,'시스템 감사인의 독립성을 가장 잘 확보한 사례는?','システム監査人の独立性を最もよく確保した例はどれか。','["監査対象システムの運用担当者とは別の組織が監査する","運用担当者が自分の作業だけを監査する","開発責任者が承認なしで監査結果を変更する","監査証拠を残さない"]','["監査対象システムの運用担当者とは別の組織が監査する","運用担当者が自分の作業だけを監査する","開発責任者が承認なしで監査結果を変更する","監査証拠を残さない"]',0,'운영과 독립된 조직이 감사','監査対象の運用部門とは別組織が監査する','감사 대상 업무로부터 독립된 위치에서 객관적으로 평가해야 한다.','監査対象業務から独立した立場で客観的に評価する必要がある。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-59' AND t.type_no=1;

