SELECT NULL,t.id,1,'감사인이 직접 접근통제 규칙을 운영하고 그 결과를 다시 감사하는 경우 가장 우려되는 것은?','監査人が自らアクセス制御を運用し，その結果を自分で監査する場合，最も懸念されることはどれか。','["独立性の低下","可用性の向上","暗号強度の向上","ネットワーク帯域の増加"]','["独立性の低下","可用性の向上","暗号強度の向上","ネットワーク帯域の増加"]',0,'독립성 저하','独立性の低下','운영 책임과 감사 책임이 같은 사람에게 집중되면 독립성과 객관성이 훼손될 수 있다.','運用責任と監査責任が同一人物に集中すると，独立性・客観性が損なわれるおそれがある。',2,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-59' AND t.type_no=3;

