SELECT NULL,t.id,1,'송금 등록자와 최종 승인자를 서로 다른 사람으로 분리하는 통제는?','振込登録者と最終承認者を別の人に分ける統制はどれか。','["職務分掌","RAID","キャッシュ","ルーティング"]','["職務分掌","RAID","キャッシュ","ルーティング"]',0,'직무분장','職務分掌','승인·실행 등의 역할을 분리해 오류와 부정 위험을 줄인다.','承認・実行などの役割を分離し，誤謬や不正のリスクを低減する。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-60' AND t.type_no=1;

