SELECT NULL,t.id,1,'한 사용자가 거래 생성과 승인까지 모두 할 수 있는 상태의 주된 위험은?','一人の利用者が取引の作成と承認を両方できる状態の主なリスクはどれか。','["不正や誤りを単独で完結できる","通信速度が遅くなる","DNS障害が増える","CPU使用率が必ず下がる"]','["不正や誤りを単独で完結できる","通信速度が遅くなる","DNS障害が増える","CPU使用率が必ず下がる"]',0,'부정/오류를 단독으로 완결할 위험','不正や誤りを単独で完結できる','상호 견제가 사라져 내부통제 위험이 커진다.','相互牽制が働かず，内部統制上のリスクが高まる。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-60' AND t.type_no=2;

