SELECT NULL,t.id,1,'SWOT 분석에서 경쟁사의 신규 진입은 일반적으로 어디에 분류되는가?','SWOT分析で競合企業の新規参入は，一般にどこへ分類されるか。','["Threat","Strength","Weakness","Opportunity"]','["Threat","Strength","Weakness","Opportunity"]',0,'Threat','Threat','경쟁사 신규 진입은 조직 외부의 불리한 환경요인이므로 Threat다.','競合企業の新規参入は組織外部の不利な環境要因なのでThreatである。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-61' AND t.type_no=1;

