SELECT NULL,t.id,1,'조직의 강한 브랜드 인지도와 시장 성장이라는 기회를 결합해 적극 확장하는 전략은 어떤 조합에 가까운가?','強いブランド認知という強みと市場成長という機会を組み合わせ，積極的に拡大する戦略はどの組合せに近いか。','["SO","ST","WO","WT"]','["SO","ST","WO","WT"]',0,'SO','SO','강점을 활용해 기회를 잡는 전략은 SO 조합이다.','強みを活用して機会を捉える戦略はSOである。',2,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-61' AND t.type_no=3;

