SELECT NULL,t.id,1,'PPM에서 시장성장률이 높고 상대적 시장점유율도 높은 사업은?','PPMで市場成長率が高く，相対的市場占有率も高い事業はどれか。','["Star","Cash Cow","Question Mark","Dog"]','["Star","Cash Cow","Question Mark","Dog"]',0,'Star','Star','고성장·고점유 영역은 Star다.','高成長・高占有率の領域はStarである。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-62' AND t.type_no=1;

