SELECT NULL,t.id,1,'원재료 공급업체 수가 매우 적어 가격 협상력이 강해지는 현상은 5 Forces 중 무엇과 관련되는가?','原材料供給業者が少数で価格交渉力が強い状況は，5 Forcesのどれに関係するか。','["売り手の交渉力","買い手の交渉力","代替品の脅威","新規参入の脅威"]','["売り手の交渉力","買い手の交渉力","代替品の脅威","新規参入の脅威"]',0,'공급자 교섭력','売り手の交渉力','공급업체가 소수이면 공급자의 협상력이 커질 수 있다.','供給業者が少数であれば，売り手の交渉力が強くなりやすい。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-63' AND t.type_no=1;

