SELECT NULL,t.id,1,'기존 제품과 다른 방식으로 같은 고객 요구를 충족하는 서비스의 등장은 어떤 경쟁요인인가?','既存製品とは異なる方法で同じ顧客ニーズを満たすサービスの登場は，どの競争要因か。','["代替品の脅威","売り手の交渉力","既存企業間競争だけ","参入障壁"]','["代替品の脅威","売り手の交渉力","既存企業間競争だけ","参入障壁"]',0,'대체재 위협','代替品の脅威','같은 필요를 다른 수단으로 충족하면 대체재가 될 수 있다.','同じニーズを別の手段で満たすものは代替品となり得る。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-63' AND t.type_no=2;

