SELECT NULL,t.id,1,'높은 초기 투자비용과 강한 규제가 일반적으로 낮추는 경쟁요인은?','高い初期投資費用と強い規制が一般に低下させる競争要因はどれか。','["新規参入の脅威","買い手の交渉力","代替品の脅威","既存競争の数"]','["新規参入の脅威","買い手の交渉力","代替品の脅威","既存競争の数"]',0,'신규 진입 위협','新規参入の脅威','진입장벽이 높아지면 신규 경쟁자의 시장 진입이 어려워진다.','参入障壁が高くなると，新規企業の参入が難しくなる。',2,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-63' AND t.type_no=3;

