SELECT NULL,t.id,1,'4P에서 유통경로와 판매장소에 해당하는 요소는?','4Pで流通経路や販売場所に該当する要素はどれか。','["Place","Product","Price","Promotion"]','["Place","Product","Price","Promotion"]',0,'Place','Place','Place는 제품이 고객에게 전달되는 유통·채널을 다룬다.','Placeは製品を顧客へ届ける流通・チャネルを扱う。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-64' AND t.type_no=1;

