SELECT NULL,t.id,1,'4C에서 고객이 구매와 이용을 얼마나 편리하게 할 수 있는지에 해당하는 요소는?','4Cで，顧客が購入・利用しやすいかという観点に該当する要素はどれか。','["Convenience","Cost","Communication","Customer Value"]','["Convenience","Cost","Communication","Customer Value"]',0,'Convenience','Convenience','접근성과 구매 편의성은 Convenience 관점이다.','アクセス性や購入のしやすさはConvenienceの観点である。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-64' AND t.type_no=2;

