SELECT NULL,t.id,1,'온라인 판매 채널 확대를 4P/4C 관점에서 연결한 것으로 가장 적절한 것은?','オンライン販売チャネルの拡大を4P/4Cで対応付けたものとして最も適切なのはどれか。','["PlaceとConvenience","PriceとCommunication","PromotionとCost","ProductとCostだけ"]','["PlaceとConvenience","PriceとCommunication","PromotionとCost","ProductとCostだけ"]',0,'Place와 Convenience','PlaceとConvenience','유통 채널 확대는 기업 관점의 Place, 고객 관점의 편의성 향상과 연결된다.','流通チャネル拡大は企業側のPlace，顧客側のConvenienceと関係する。',2,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-64' AND t.type_no=3;

