SELECT NULL,t.id,1,'판매단가 100, 단위변동비 60, 고정비 4,000일 때 손익분기 판매량은?','販売単価100，単位変動費60，固定費4,000のとき，損益分岐点販売数量は幾つか。','["40","67","100","160"]','["40","67","100","160"]',2,'100개','100個','단위 공헌이익은 40, 따라서 4000/40=100개다.','単位限界利益は40なので，4,000/40=100個である。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-65' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'단위당 공헌이익의 계산식은?','単位限界利益の計算式はどれか。','["販売単価-単位変動費","販売単価+固定費","固定費-売上高","売上高÷固定費"]','["販売単価-単位変動費","販売単価+固定費","固定費-売上高","売上高÷固定費"]',0,'판매단가 - 단위변동비','販売単価-単位変動費','한 단위를 팔아 고정비와 이익에 기여하는 금액이다.','1単位販売したとき，固定費回収と利益へ寄与する額である。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-65' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'고정비가 증가하고 판매단가와 단위변동비가 변하지 않을 때 손익분기 판매량은 일반적으로 어떻게 되는가?','固定費が増加し，販売単価と単位変動費が変わらないとき，損益分岐点販売数量は一般にどうなるか。','["増加する","減少する","変わらない","必ず0になる"]','["増加する","減少する","変わらない","必ず0になる"]',0,'증가','増加する','BEP 수량=고정비/단위공헌이익이므로 분자가 커지면 수량이 늘어난다.','BEP数量=固定費/単位限界利益なので，固定費が増えれば必要数量も増える。',2,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-65' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'투자액 1,000, 이익 120일 때 ROI는?','投資額1,000，利益120のとき，ROIは何%か。','["8%","12%","20%","120%"]','["8%","12%","20%","120%"]',1,'12%','12%','ROI=이익/투자액×100=120/1000×100=12%.','ROI=利益/投資額×100=120/1,000×100=12%である。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-66' AND t.type_no=1;

