SELECT NULL,t.id,1,'ROI 계산에서 분모로 사용하는 값은?','ROIの計算で分母に用いる値はどれか。','["投資額","利益","売上高だけ","固定費だけ"]','["投資額","利益","売上高だけ","固定費だけ"]',0,'투자액','投資額','ROI는 투자 대비 이익의 비율이다.','ROIは投資に対する利益の比率である。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-66' AND t.type_no=2;

