SELECT NULL,t.id,1,'서로 다른 투자안의 ROI를 비교할 때 주의할 점으로 가장 적절한 것은?','異なる投資案のROIを比較するときの注意点として最も適切なものはどれか。','["利益と投資額の対象期間・定義をそろえる","売上高だけ比較すればよい","投資額を無視する","単位が違ってもそのまま比較する"]','["利益と投資額の対象期間・定義をそろえる","売上高だけ比較すればよい","投資額を無視する","単位が違ってもそのまま比較する"]',0,'기간과 정의를 맞춰 비교','利益と投資額の対象期間・定義をそろえる','비율 비교는 분자·분모의 기준과 기간이 같아야 의미가 있다.','比率比較では，分子・分母の定義と対象期間をそろえる必要がある。',2,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-66' AND t.type_no=3;

