SELECT NULL,t.id,1,'프로그램의 소스코드와 같은 창작적 표현을 보호하는 권리로 가장 적절한 것은?','プログラムのソースコードのような創作的表現を保護する権利として最も適切なものはどれか。','["著作権","特許権だけ","商標権だけ","所有権だけ"]','["著作権","特許権だけ","商標権だけ","所有権だけ"]',0,'저작권','著作権','프로그램 코드는 저작물로 보호될 수 있다.','プログラムのコードは著作物として保護され得る。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-67' AND t.type_no=1;

