SELECT NULL,t.id,1,'저작권과 특허권의 차이로 가장 적절한 것은?','著作権と特許権の違いとして最も適切なものはどれか。','["著作権は表現，特許権は技術的発明を主に保護する","両者とも必ず同じ対象を保護する","著作権は技術的発明だけを保護する","特許権は文章表現だけを保護する"]','["著作権は表現，特許権は技術的発明を主に保護する","両者とも必ず同じ対象を保護する","著作権は技術的発明だけを保護する","特許権は文章表現だけを保護する"]',0,'저작권=표현, 특허=기술적 발명','著作権は表現，特許権は技術的発明を主に保護する','보호 대상의 성격이 다르므로 먼저 표현인지 기술적 발명인지 구분한다.','保護対象の性質が異なるため，表現か技術的発明かを区別する。',2,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-67' AND t.type_no=3;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'서비스 목적에 필요하지 않은 식별정보를 수집하지 않는 것은 개인정보 처리의 어떤 원칙과 가장 관련 있는가?','サービス目的に不要な識別情報を収集しないことは，個人情報取扱いのどの考え方に最も関係するか。','["必要最小限の収集","無制限収集","目的外利用","公開優先"]','["必要最小限の収集","無制限収集","目的外利用","公開優先"]',0,'최소수집','必要最小限の収集','업무 목적에 필요한 범위만 수집하면 개인정보 노출 위험을 줄일 수 있다.','利用目的に必要な範囲だけ収集することで，個人情報の取扱いリスクを抑えられる。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-68' AND t.type_no=1;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'표준화의 주된 효과로 가장 적절한 것은?','標準化の主な効果として最も適切なものはどれか。','["製品・システム間の互換性や共通性を高める","全ての製品を同一価格にする","競争を完全になくす","セキュリティ事故を必ずゼロにする"]','["製品・システム間の互換性や共通性を高める","全ての製品を同一価格にする","競争を完全になくす","セキュリティ事故を必ずゼロにする"]',0,'호환성·공통성 향상','製品・システム間の互換性や共通性を高める','공통 규격을 통해 상호운용성과 품질 관리가 쉬워질 수 있다.','共通規格によって相互運用性や品質管理を向上させやすい。',1,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-68' AND t.type_no=2;

INSERT OR REPLACE INTO ap_concept_questions (id,problem_type_id,question_no,question_ko,question_ja,choices_ko_json,choices_ja_json,correct_choice,answer_ko,answer_ja,explanation_ko,explanation_ja,difficulty,sort_order)
SELECT NULL,t.id,1,'개인정보를 원래 수집 목적과 다른 목적으로 이용하려 할 때 가장 먼저 확인해야 할 사항으로 적절한 것은?','個人情報を当初の収集目的とは異なる目的で利用しようとするとき，最初に確認すべき事項として適切なものはどれか。','["利用目的と法的根拠・同意の有無","CPUクロック数","RAIDレベル","DNS TTL"]','["利用目的と法的根拠・同意の有無","CPUクロック数","RAIDレベル","DNS TTL"]',0,'이용 목적과 법적 근거/동의','利用目的と法的根拠・同意の有無','목적외 이용 여부와 적법한 처리 근거를 확인해야 한다.','目的外利用に当たるか，適法な処理根拠があるかを確認する必要がある。',2,1 FROM ap_concept_problem_types t JOIN ap_concepts c ON c.id=t.concept_id WHERE c.concept_code='A-68' AND t.type_no=3;
